// Presentation only: the chain result chooses the landing, never this chase.
export function currencySelectionFrames(selectedIndex, { speed = 1, quick = false } = {}) {
  const rate = Math.max(.5, Math.min(3, Number(speed) || 1));
  const target = Math.max(0, Math.min(2, Number(selectedIndex) || 0));
  const indices = quick || rate > 1 ? [0, 1, 2, 1, 0] : [0, 1, 2, 1, 0, 1, 2, 1, 0];
  for (let i = 1; i <= target; i++) indices.push(i);
  const duration = Math.max(quick ? 650 : 780, (quick ? 1000 : 1450) / rate);
  const weights = indices.map((_, i) => 1 + 2 * (i / (indices.length - 1)) ** 2);
  const total = weights.reduce((sum, value) => sum + value, 0);
  return indices.map((index, i) => ({ index, dwell: Math.round(duration * weights[i] / total) }));
}
